import pandas as pd
import re

df = pd.read_csv("housing.csv")

def column_tokens(col):
    return re.findall(r"[a-z0-9]+", col.lower())

# Strategy 1: find a column whose tokens include 'median', 'house', and 'value'
candidates = []
for col in df.columns:
    toks = set(column_tokens(col))
    if {"median", "house", "value"}.issubset(toks):
        candidates.append(col)

# Strategy 2: if none, find column with 'median' and 'value'
if not candidates:
    for col in df.columns:
        toks = set(column_tokens(col))
        if {"median", "value"}.issubset(toks):
            candidates.append(col)

# Strategy 3: if still none, find a column named exactly common variants
if not candidates:
    common_names = ["median_house_value", "median-house-value", "median house value", "medianvalue", "median_value"]
    lowered = {col.lower(): col for col in df.columns}
    for name in common_names:
        if name in lowered:
            candidates.append(lowered[name])

# Strategy 4: fallback to any numeric column containing 'median' token
if not candidates:
    for col in df.columns:
        toks = set(column_tokens(col))
        if "median" in toks:
            if pd.api.types.is_numeric_dtype(df[col]) or df[col].dropna().apply(lambda x: isinstance(x, (int, float))).all():
                candidates.append(col)

# Compute result
if candidates:
    col = candidates[0]
    numeric_series = pd.to_numeric(df[col], errors="coerce")
    result = numeric_series.mean()
else:
    result = {"error": "No suitable median house value column found", "columns": list(df.columns)}

import pandas as pd

df = pd.read_csv("housing.csv")

def _normalize(col):
    s = col.lower()
    # replace common separators with spaces and remove other punctuation
    for ch in ['_', '-', '.', '/']:
        s = s.replace(ch, ' ')
    s = ''.join(ch if (ch.isalnum() or ch.isspace()) else ' ' for ch in s)
    return s

cols = df.columns.tolist()
target_col = None
tokens = ['median', 'house', 'value']

# 1) look for columns containing all tokens
for col in cols:
    s = _normalize(col)
    if all(tok in s for tok in tokens):
        target_col = col
        break

# 2) fallback: median + value or median + house
if target_col is None:
    for col in cols:
        s = _normalize(col)
        if 'median' in s and ('value' in s or 'house' in s):
            target_col = col
            break

# 3) fallback: any column with 'median'
if target_col is None:
    for col in cols:
        if 'median' in _normalize(col):
            target_col = col
            break

if target_col is None:
    raise KeyError("Could not find a column corresponding to median house value in the CSV.")

# ensure numeric
series = pd.to_numeric(df[target_col], errors='coerce').dropna()
if series.empty:
    raise ValueError(f"Column '{target_col}' contains no numeric data.")

smin = series.min()
smax = series.max()
smed = series.median()

result = {'column': target_col, 'min': float(smin), 'max': float(smax), 'median': float(smed)}
